import sys

def doctorStrange(N: int, M: int, graph: list) -> int:
    adj = [[] for _ in range(N + 1)]
    for u, v in graph:
        adj[u].append(v)
        adj[v].append(u)

    disc = [-1] * (N + 1)
    low = [-1] * (N + 1)
    parent = [0] * (N + 1)
    ap = [False] * (N + 1)
    timer = [0]

    def dfs(u):
        children = 0
        disc[u] = low[u] = timer[0]
        timer[0] += 1

        for v in adj[u]:
            if disc[v] == -1:
                children += 1
                parent[v] = u
                dfs(v)
                low[u] = min(low[u], low[v])

                if parent[u] != 0 and low[v] >= disc[u]:
                    ap[u] = True
            elif v != parent[u]:
                low[u] = min(low[u], disc[v])

        if parent[u] == 0 and children > 1:
            ap[u] = True

    for i in range(1, N + 1):
        if disc[i] == -1:
            dfs(i)

    return sum(ap[1:])

def main():
    input_data = sys.stdin.read().split()
    idx = 0
    if not input_data:
        return
    N = int(input_data[idx])
    idx += 1
    M = int(input_data[idx])
    idx += 1

    graph = []
    for _ in range(M):
        u = int(input_data[idx])
        v = int(input_data[idx + 1])
        idx += 2
        graph.append((u, v))

    result = doctorStrange(N, M, graph)
    print(result)

if __name__ == "__main__":
    main()
